package kz.printlab.dto; import jakarta.validation.constraints.Size; public class ProfileUpdateRequest { @Size(max=120) private String fullName; @Size(max=30) private String phone; @Size(max=2000) private String deliveryAddress; public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDeliveryAddress(){return deliveryAddress;} public void setDeliveryAddress(String v){deliveryAddress=v;}}
